live=[]
def cleanup_failed_scope():
 for process in live:
  if process.poll()is None:
   process.send_signal(signal.SIGINT)
   try:process.communicate(timeout=10)
   except subprocess.TimeoutExpired:process.kill();process.communicate(timeout=4)
