 env=dict(os.environ,LD_PRELOAD=str(a.library),SUITECUT_ATTACHMENT_TEST_HOLD=hold,SUITECUT_ATTACHMENT_TEST_MARKER=str(root/'syscall.marker'),SUITECUT_ATTACHMENT_TEST_RELEASE=str(root/'release'),ACTUAL_ALLOW_SKIP=str(root/'allow-skip'),ACTUAL_ACCEPTED_SKIP=str(root/'accepted'),ACTUAL_ADMITTED=str(root/'admitted.marker'),ACTUAL_AFTER_EACH=str(root/'afterEach'))
