 v=json.loads((root/'actual.json').read_text());assert state(writer)is None and all(state(w['pid'])is None for w in v['workers']);rows.append({'scope':root.name,'actualExitCode':process.returncode,'actualSyscallPid':writer,'report':str(root/'actual.json')});return v
